<?php/** * Cron jobs for Agency health monitoring + Scheduled Reports — V1.0.5 * LOCAL-FIRST — No external API calls. * * @package MegaGovern * @since   1.0.5 */namespace MegaGovern;if ( ! defined( 'ABSPATH' ) ) {	exit;}class Cron {	const HEALTH_HOOK = 'megagovern_hourly_health_check';	const REPORT_HOOK = 'megagovern_daily_report_check';	public function __construct() {		add_action( self::HEALTH_HOOK, array( $this, 'check_client_health' ) );		add_action( self::REPORT_HOOK, array( $this, 'run_scheduled_report' ) );	}	/**	 * Schedule events — call on activation, not on every new Cron().	 */	public static function schedule(): void {		if ( ! wp_next_scheduled( self::HEALTH_HOOK ) ) {			wp_schedule_event( time(), 'hourly', self::HEALTH_HOOK );		}		if ( ! wp_next_scheduled( self::REPORT_HOOK ) ) {			wp_schedule_event( time(), 'daily', self::REPORT_HOOK );		}	}	/**	 * Wrapper for Reports::send_scheduled_report() called by daily cron.	 */	public function run_scheduled_report(): void {		if ( class_exists( '\MegaGovern\Reports' ) && method_exists( '\MegaGovern\Reports', 'send_scheduled_report' ) ) {			\MegaGovern\Reports::send_scheduled_report();		}	}	/**	 * Check health of all agency client sites.	 */	public function check_client_health(): void {		if ( ! class_exists( '\MegaGovern\License' ) || ! License::is_agency() ) {			return;		}		// Lock 10 min to prevent overlap		$lock = 'megagovern_health_check_lock';		if ( get_transient( $lock ) ) {			return;		}		set_transient( $lock, 1, 10 * MINUTE_IN_SECONDS );		$sites = class_exists( '\MegaGovern\Agency' ) ? Agency::get_sites() : array();		if ( empty( $sites ) ) {			delete_transient( $lock );			return;		}		$alerts         = get_option( 'megagovern_agency_alerts', array() );		$now            = current_time( 'mysql' );		$all_new_alerts = array();		foreach ( $sites as $id => $site ) {			$prev_score = (int) ( $site['score'] ?? 100 );			$site_name  = $site['name'] ?? __( 'Unknown Site', 'megagovern' );			$health = $this->get_local_site_health( (string) $id );			if ( ! $health ) {				continue;			}			$score              = (int) ( $health['score'] ?? 0 );			$declared           = (int) ( $health['declared'] ?? 0 );			$undeclared         = (int) ( $health['undeclared'] ?? 0 );			$last_declared_days = (int) ( $health['last_declared_days'] ?? 0 );			$sites[ $id ]['score']        = $score;			$sites[ $id ]['declared']     = $declared;			$sites[ $id ]['undeclared']   = $undeclared;			$sites[ $id ]['last_checked'] = $now;			$new_alerts = array();			if ( $prev_score > 0 && $score < 80 && $prev_score >= 80 ) {				$new_alerts[] = array(					'site_id'   => $id,					'site_name' => $site_name,					'type'      => 'score_drop',					'message'   => sprintf(						/* translators: 1: previous score percentage, 2: current score percentage */						__( 'Score dropped: %1$d%% → %2$d%%', 'megagovern' ),						$prev_score,						$score					),					'reason'    => sprintf(						/* translators: %d: number of undeclared posts */						__( '%d undeclared posts', 'megagovern' ),						$undeclared					),					'time'      => $now,				);			}			if ( $undeclared > 0 && $last_declared_days > 7 ) {				$new_alerts[] = array(					'site_id'   => $id,					'site_name' => $site_name,					'type'      => 'undeclared_stale',					'message'   => sprintf(						/* translators: 1: number of undeclared posts, 2: days since last declaration */						__( '%1$d undeclared posts — no declarations in %2$d days', 'megagovern' ),						$undeclared,						$last_declared_days					),					'reason'    => __( 'Content needs source declaration', 'megagovern' ),					'time'      => $now,				);			}			if ( ! empty( $new_alerts ) ) {				$all_new_alerts = array_merge( $all_new_alerts, $new_alerts );			}		}		if ( ! empty( $all_new_alerts ) ) {			$alerts = array_merge( $all_new_alerts, $alerts );			$this->send_alert_email( $all_new_alerts );		}		$alerts = array_slice( $alerts, 0, 50 );		update_option( 'megagovern_agency_sites', $sites );		update_option( 'megagovern_agency_alerts', $alerts );		delete_transient( $lock );	}	/**	 * Get health data — now respects multisite and uses Registry for undeclared.	 */	private function get_local_site_health( string $site_id ): ?array {		global $wpdb;		$is_multisite = is_multisite() && is_numeric( $site_id );		if ( $is_multisite ) {			switch_to_blog( (int) $site_id );		}		$declared = 0;		if ( class_exists( '\MegaGovern\Registry' ) && method_exists( '\MegaGovern\Registry', 'count_total' ) ) {			$declared = (int) Registry::count_total();		} else {			// phpcs:ignore WordPress.DB.DirectDatabaseQuery.DirectQuery, WordPress.DB.DirectDatabaseQuery.NoCaching			$declared = (int) $wpdb->get_var(				$wpdb->prepare(					"SELECT COUNT(*) FROM {$wpdb->postmeta} WHERE meta_key = %s AND meta_value IN ('human','ai_assisted','ai_generated','deepfake')",					'_megagovern_declaration'				)			);		}		$undeclared = 0;		if ( class_exists( '\MegaGovern\Registry' ) && method_exists( '\MegaGovern\Registry', 'count_undeclared' ) ) {			$undeclared = (int) Registry::count_undeclared();		} else {			// phpcs:ignore WordPress.DB.DirectDatabaseQuery.DirectQuery, WordPress.DB.DirectDatabaseQuery.NoCaching			$undeclared = (int) $wpdb->get_var(				"SELECT COUNT(*) FROM {$wpdb->posts} p				 LEFT JOIN {$wpdb->postmeta} pm ON p.ID = pm.post_id AND pm.meta_key = '_megagovern_declaration'				 WHERE p.post_status = 'publish'				 AND p.post_type IN ('post','page')				 AND pm.meta_id IS NULL"			);		}		// phpcs:ignore WordPress.DB.DirectDatabaseQuery.DirectQuery, WordPress.DB.DirectDatabaseQuery.NoCaching		$last_declared = $wpdb->get_var(			"SELECT meta_value FROM {$wpdb->postmeta}			 WHERE meta_key = '_megagovern_declared_at'			 ORDER BY meta_value DESC LIMIT 1"		);		$last_declared_days = 0;		if ( $last_declared ) {			$ts = strtotime( $last_declared );			if ( $ts ) {				$last_declared_days = (int) round( ( time() - $ts ) / DAY_IN_SECONDS );			}		}		$total = $declared + $undeclared;		$score = $total > 0 ? (int) round( ( $declared / $total ) * 100 ) : 0;		if ( $is_multisite ) {			restore_current_blog();		}		return array(			'score'              => $score,			'declared'           => $declared,			'undeclared'         => $undeclared,			'last_declared_days' => $last_declared_days,		);	}	/**	 * Send batched email — 1 email for all alerts, not 1 per alert.	 */	private function send_alert_email( array $alerts ): void {		$email = get_option( 'megagovern_report_email', get_bloginfo( 'admin_email' ) );		if ( empty( $email ) || ! is_email( $email ) || empty( $alerts ) ) {			return;		}		$site_count = count( array_unique( array_column( $alerts, 'site_name' ) ) );		$subject    = sprintf(			/* translators: 1: number of alerts, 2: number of sites */			'[MegaGovern] Agency Alert — %1$d issue%2$s across %3$d site%4$s',			count( $alerts ),			count( $alerts ) > 1 ? 's' : '',			$site_count,			$site_count > 1 ? 's' : ''		);		$body  = "=== MegaGovern Agency Alert ===\n\n";		foreach ( $alerts as $alert ) {			$body .= sprintf( "Site: %s\n", $alert['site_name'] ?? 'Unknown' );			$body .= sprintf( "Type: %s\n", strtoupper( str_replace( '_', ' ', $alert['type'] ?? 'general' ) ) );			$body .= sprintf( "Message: %s\n", $alert['message'] ?? '' );			$body .= sprintf( "Reason: %s\n", $alert['reason'] ?? '' );			$body .= sprintf( "Time: %s\n", $alert['time'] ?? current_time( 'mysql' ) );			$body .= "---\n";		}		$body .= "\nAction Required: Please review the Agency Hub.\n";		$body .= sprintf( "Open Dashboard: %s\n\n", admin_url( 'admin.php?page=megagovern-agency' ) );		$body .= "---\nThis is an automated alert from MegaGovern.";		wp_mail( $email, $subject, $body );	}	public static function get_site_health( string $site_id ): ?array {		$instance = new self();		return $instance->get_local_site_health( $site_id );	}	public static function force_health_check(): bool {		if ( ! current_user_can( 'manage_options' ) ) {			return false;		}		$instance = new self();		$instance->check_client_health();		return true;	}	public static function get_last_health_check(): string {		$sites      = class_exists( '\MegaGovern\Agency' ) ? Agency::get_sites() : array();		$last_check = '';		foreach ( $sites as $site ) {			if ( isset( $site['last_checked'] ) && $site['last_checked'] > $last_check ) {				$last_check = $site['last_checked'];			}		}		return $last_check ?: __( 'Never', 'megagovern' );	}	public static function get_alert_count( string $type = 'all' ): int {		$alerts = get_option( 'megagovern_agency_alerts', array() );		if ( 'all' === $type ) {			return count( $alerts );		}		$count = 0;		foreach ( $alerts as $alert ) {			if ( ( $alert['type'] ?? '' ) === $type ) {				$count++;			}		}		return $count;	}	public static function cleanup(): void {		foreach ( array( self::HEALTH_HOOK, self::REPORT_HOOK ) as $hook ) {			$timestamp = wp_next_scheduled( $hook );			if ( $timestamp ) {				wp_unschedule_event( $timestamp, $hook );			}			wp_clear_scheduled_hook( $hook );		}		delete_transient( 'megagovern_health_check_lock' );		delete_transient( 'megagovern_report_sending_lock' );	}}